from datetime import date, timedelta
import calendar


def recur(start: str, rule: str, count: int) -> list[str]:
    def add_months(year: int, month: int, delta: int) -> tuple[int, int]:
        total = year * 12 + (month - 1) + delta
        return total // 12, total % 12 + 1

    def nth_weekday(year: int, month: int, n: int, wd: int):
        if n == -1:
            last_day = calendar.monthrange(year, month)[1]
            last = date(year, month, last_day)
            return last - timedelta(days=(last.weekday() - wd) % 7)
        first = date(year, month, 1)
        day = 1 + (wd - first.weekday()) % 7 + (n - 1) * 7
        if day > calendar.monthrange(year, month)[1]:
            return None
        return date(year, month, day)

    wd_index = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}
    year, month, day = (int(part) for part in start.split("-"))
    start_date = date(year, month, day)
    parts = rule.split(" ")
    kind = parts[0]
    step = int(parts[1])
    out: list[str] = []

    if kind == "DAILY":
        cur = start_date
        while len(out) < count:
            out.append(cur.isoformat())
            cur += timedelta(days=step)
        return out

    if kind == "WEEKLY":
        days = sorted(wd_index[token] for token in parts[2].split(","))
        monday = start_date - timedelta(days=start_date.weekday())
        week = 0
        while len(out) < count:
            week_monday = monday + timedelta(days=7 * week)
            for wd in days:
                cur = week_monday + timedelta(days=wd)
                if cur >= start_date:
                    out.append(cur.isoformat())
                    if len(out) == count:
                        return out
            week += step
        return out

    if kind == "MONTHLY" and len(parts) == 3:
        dom = int(parts[2])
        index = 0
        while len(out) < count:
            year, month = add_months(start_date.year, start_date.month, index)
            last_day = calendar.monthrange(year, month)[1]
            if dom == -1:
                cur = date(year, month, last_day)
            elif dom <= last_day:
                cur = date(year, month, dom)
            else:
                index += step
                continue
            if cur >= start_date:
                out.append(cur.isoformat())
            index += step
        return out

    if kind == "MONTHLY":
        n = int(parts[2])
        wd = wd_index[parts[3]]
        index = 0
        while len(out) < count:
            year, month = add_months(start_date.year, start_date.month, index)
            cur = nth_weekday(year, month, n, wd)
            if cur is not None and cur >= start_date:
                out.append(cur.isoformat())
            index += step
        return out

    mm, dd = (int(part) for part in parts[2].split("-"))
    index = 0
    while len(out) < count:
        year = start_date.year + index
        try:
            cur = date(year, mm, dd)
        except ValueError:
            index += step
            continue
        if cur >= start_date:
            out.append(cur.isoformat())
        index += step
    return out
